/*
 Problem: 3568. Minimum Moves to Clean the Classroom
 Language: cpp
 Runtime: 1200 ms (16.69%)
 Memory: 399 MB (18.32%)
 Tags: Array, Hash Table, Bit Manipulation, Breadth-First Search, Matrix
*/
class Solution {
public:
    int minMoves(vector<string>& classroom, int energy) {
        int m = classroom.size(), n = classroom[0].size();
        int sx, sy, cnt = 0;

        vector<vector<int>> id(m, vector<int>(n, -1));

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (classroom[i][j] == 'S')
                    sx = i, sy = j;
                else if (classroom[i][j] == 'L')
                    id[i][j] = cnt++;
            }
        }

        int full = (1 << cnt) - 1;

        queue<array<int, 4>> q;
        q.push({sx, sy, energy, 0});

        vector<vector<vector<vector<bool>>>> vis(
            m,
            vector<vector<vector<bool>>>(
                n,
                vector<vector<bool>>(
                    energy + 1,
                    vector<bool>(1 << cnt, false)
                )
            )
        );

        vis[sx][sy][energy][0] = true;

        int dx[] = {1, -1, 0, 0};
        int dy[] = {0, 0, 1, -1};
        int step = 0;

        while (!q.empty()) {
            int sz = q.size();

            while (sz--) {
                auto [x, y, e, mask] = q.front();
                q.pop();

                if (mask == full)
                    return step;

                for (int d = 0; d < 4; d++) {
                    int nx = x + dx[d];
                    int ny = y + dy[d];

                    if (nx < 0 || nx >= m || ny < 0 || ny >= n)
                        continue;

                    if (classroom[nx][ny] == 'X' || e == 0)
                        continue;

                    int ne = e - 1;
                    int nmask = mask;

                    if (classroom[nx][ny] == 'L')
                        nmask |= 1 << id[nx][ny];

                    if (classroom[nx][ny] == 'R')
                        ne = energy;

                    if (vis[nx][ny][ne][nmask])
                        continue;

                    vis[nx][ny][ne][nmask] = true;
                    q.push({nx, ny, ne, nmask});
                }
            }

            ++step;
        }

        return -1;
    }
};
